/* audio_demo - sounds, sprites, a looping bus, a streamed ogg.
 *
 *   audio_demo [--frames N] [--screenshot out.png] [--gpu-driver vulkan|direct3d12]
 *
 * Sounds come from examples/audio (generated by make_sounds.py; gong.ogg is CC0). The asset root
 * is "../../examples/audio" relative to the executable, i.e. build/<preset>/audio_demo.exe.
 *
 * Interactive: click a square (or press 1-4) to play beep / tone sprites / gong (streamed) /
 * toggle the humming loop on the "music" bus. M mutes everything. A square is bright while its
 * sound plays.
 * With --frames the demo plays a fixed sequence instead and logs every completion, e.g.
 *   audio_demo --frames 480   (about 8 s at 60 Hz: long enough for the 5.6 s gong to finish)
 */
#include "braty/braty_main.h"

static bool g_scripted = false;

enum { PAD_COUNT = 4 };

typedef struct demo_state {
    br_sound         *beep;
    br_sound         *tones;
    br_sound         *gong;
    br_sound         *hum;
    int               music_bus;
    br_sound_instance playing[PAD_COUNT];
    br_node           pads[PAD_COUNT];
    int               next_tone;
    int               completed;
    bool              muted;
} demo_state;

static const char *g_pad_names[PAD_COUNT] = { "beep", "tones", "gong", "hum" };

static void on_complete(br_engine *e, br_sound_instance i, void *user)
{
    (void)e;
    (void)i;
    demo_state *s = user;
    s->completed++;
    br_log_info("audio_demo: a sound finished (%d so far)", s->completed);
}

static void play_pad(br_engine *e, demo_state *s, int pad)
{
    br_audio_play_desc play = br_audio_play_defaults();
    play.on_complete = on_complete;
    play.user = s;
    if (pad == 0) {
        play.volume = 0.5f;
        s->playing[0] = br_audio_play(e, s->beep, &play);
    } else if (pad == 1) {
        const char *names[3] = { "c", "e", "g" };
        play.sprite = names[s->next_tone % 3];
        play.pan = (float)(s->next_tone % 3) - 1.0f;   /* left, centre, right */
        s->next_tone++;
        s->playing[1] = br_audio_play(e, s->tones, &play);
    } else if (pad == 2) {
        s->playing[2] = br_audio_play(e, s->gong, &play);
    } else if (br_audio_is_playing(e, s->playing[3])) {
        br_audio_stop(e, s->playing[3]);
    } else {
        play.loop = true;
        play.bus = s->music_bus;
        play.on_complete = NULL;   /* loops never complete */
        s->playing[3] = br_audio_play(e, s->hum, &play);
    }
    br_log_info("audio_demo: pad '%s' (%u instances playing)", g_pad_names[pad], br_audio_instance_count(e));
}

static void pad_click(br_engine *e, br_event *ev, void *user)
{
    demo_state *s = user;
    for (int i = 0; i < PAD_COUNT; i++) {
        if (br_node_equal(ev->current_target, s->pads[i])) {
            play_pad(e, s, i);
        }
    }
}

static void demo_system(br_engine *e, float dt, void *user)
{
    (void)dt;
    demo_state *s = user;
    SDL_Scancode keys[PAD_COUNT] = { SDL_SCANCODE_1, SDL_SCANCODE_2, SDL_SCANCODE_3, SDL_SCANCODE_4 };
    for (int i = 0; i < PAD_COUNT; i++) {
        if (br_input_key_pressed(e, keys[i])) {
            play_pad(e, s, i);
        }
        float glow = br_audio_is_playing(e, s->playing[i]) ? 1.0f : 0.35f;
        br_node_set_alpha(e, s->pads[i], glow);
    }
    if (br_input_key_pressed(e, SDL_SCANCODE_M)) {
        s->muted = !s->muted;
        br_audio_set_muted(e, s->muted);
    }
    /* the hum pans slowly left and right */
    br_audio_set_pan(e, s->playing[3], SDL_sinf((float)br_ticker_elapsed(e)));
}

/* Fixed sequence for --frames runs (frame numbers at 60 Hz). */
static void script_system(br_engine *e, float dt, void *user)
{
    (void)dt;
    demo_state *s = user;
    uint64_t f = br_ticker_frame(e);
    if (f == 1 || f == 20 || f == 40 || f == 60) {
        play_pad(e, s, f == 1 ? 0 : 1);   /* beep, then the three tone sprites */
    } else if (f == 80) {
        play_pad(e, s, 3);                /* start the loop on the music bus */
        play_pad(e, s, 2);                /* streamed gong */
    } else if (f == 200) {
        br_audio_bus_set_volume(e, s->music_bus, 0.3f);
    } else if (f == 300) {
        play_pad(e, s, 3);                /* stop the loop */
    }
}

static void demo_shutdown(br_engine *e, void *user)
{
    demo_state *s = user;
    br_log_info("audio_demo: device open: %s, sounds completed: %d", br_audio_device_open(e) ? "yes" : "no",
                s->completed);
    br_free(s);
}

static bool demo_init(br_engine *e)
{
    demo_state *s = br_alloc(sizeof(demo_state));
    if (s == NULL) {
        return false;
    }
    br_engine_on_shutdown(e, demo_shutdown, s);

    br_audio_set_stream_threshold(e, 2.0f);   /* stream the 5.6 s gong to show streaming */
    s->beep = br_sound_load(e, "beep.wav");
    s->tones = br_sound_load(e, "tones.wav");
    s->gong = br_sound_load(e, "gong.ogg");
    s->hum = br_sound_load(e, "hum.wav");
    if (s->beep == NULL || s->tones == NULL || s->gong == NULL || s->hum == NULL) {
        return false;
    }
    br_sound_add_sprite(e, s->tones, "c", 0.0f, 0.2f);
    br_sound_add_sprite(e, s->tones, "e", 0.25f, 0.2f);
    br_sound_add_sprite(e, s->tones, "g", 0.5f, 0.2f);
    s->music_bus = br_audio_bus_create(e, "music");
    br_log_info("audio_demo: gong %.2f s, streaming: %s", br_sound_duration(s->gong),
                br_sound_is_streaming(s->gong) ? "yes" : "no");

    uint32_t colors[PAD_COUNT] = { 0x3a7bd5, 0x2fa36b, 0xe0a030, 0x9b59b6 };
    for (int i = 0; i < PAD_COUNT; i++) {
        br_node pad = br_sprite_create(e, br_texture_white(e));
        br_sprite_set_size(e, pad, 200, 200);
        br_node_set_position(e, pad, 140.0f + (float)i * 260.0f, 260.0f);
        br_node_set_tint(e, pad, br_color_from_hex(colors[i], 1.0f));
        br_node_set_event_mode(e, pad, BR_EVENT_MODE_STATIC);
        br_node_set_cursor(e, pad, SDL_SYSTEM_CURSOR_POINTER);
        br_node_on(e, pad, BR_EVENT_CLICK, pad_click, s);
        br_node_add_child(e, br_scene_root(e), pad);
        s->pads[i] = pad;
    }
    br_system_add(e, "demo.audio", BR_PHASE_UPDATE, 0, demo_system, s);
    if (g_scripted) {
        br_system_add(e, "demo.script", BR_PHASE_UPDATE, -1, script_system, s);
    }
    return true;
}

br_app_desc br_main(int argc, char **argv)
{
    for (int i = 1; i < argc; i++) {
        if (SDL_strcmp(argv[i], "--frames") == 0) {
            g_scripted = true;
        }
    }
    br_app_desc desc;
    SDL_zero(desc);
    desc.title = "Braty - audio";
    desc.width = 1280;
    desc.height = 720;
    desc.asset_root = "../../examples/audio";
    desc.init = demo_init;
    return desc;
}
